def find_path(graph, start, goal):
    # Implementing a simple DFS to find the path
    def dfs(node, path, visited):
        if node == goal:
            return path + [node]
        visited.add(node)
        path.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                result = dfs(neighbor, path[:], visited.copy())
                if result is not None:
                    return result
        return None

    visited = set()
    return dfs(start, [start], visited)

