def find_path(graph, start, goal):
    # Initialize open and closed sets
    open_set = {start}
    closed_set = set()

    # Initialize parent dictionary
    parents = {start: None}

    # Initialize the g_score dictionary
    # g_score[start] is the cost from start along the path to start
    g_score = {start: 0}

    # Initialize f_score dictionary
    # f_score[start] = g_score[start] + heuristic(start, goal)
    # We'll use A* here with a simple heuristic (Manhattan distance)
    f_score = {node: float('inf') for node in graph}
    f_score[start] = heuristic(start, goal)

    while open_set:
        # Choose the node with the lowest f_score
        current = min(open_set, key=lambda node: f_score[node])

        # Check if the goal is reached
        if current == goal:
            path = reconstruct_path(parents, current)
            if path is not None:
                return path
            else:
                return None

        # Mark the current node as explored
        open_set.remove(current)
        closed_set.add(current)

        # Explore the neighbors of the current node
        for neighbor in graph[current]:
            if neighbor in closed_set:
                continue

            # Compute tentative g_score
            tentative_g_score = g_score[current] + 1  # Assuming all edges have equal weight

            if neighbor not in open_set or tentative_g_score < g_score[neighbor]:
                # This path to the neighbor is better than any previous one
                parents[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = g_score[neighbor] + heuristic(neighbor, goal)

                # Add the neighbor to the open set
                if neighbor not in open_set:
                    open_set.add(neighbor)

    # If we reach here, it means the goal is unreachable
    return None

def heuristic(a, b):
    # Simple heuristic (Manhattan distance)
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def reconstruct_path(parents, current):
    path = [current]
    while current is not None:
        current = parents[current]
        if current is not None:
            path.append(current)
    return path[::-1]
